      if (hash.has(obj)) {
          return hash.get(obj);
      }

      var clone = Object.create(Object.getPrototypeOf(obj));
      hash.set(obj, clone);

      for (var i in obj) {
          if (obj[i] != null && typeof obj[i] == "object")
              clone[i] = cloneObject(obj[i], hash);
          else
              clone[i] = obj[i];
      }
      return clone;
  }

  This version uses a WeakMap to keep track of already cloned objects, which allows it to handle circular references without causing an infinite loop. It also uses Object.create to preserve the prototype chain of the original object.

